import statistics


def task_func(LETTERS):
    random_dict = {
        letter: [random.randint(1, 100) for _ in range(5)] for letter in LETTERS
    }
    return dict(
        sorted(
            random_dict.items(),
            key=lambda item: statistics.mean(item[1]),
            reverse=True,
        )
    )
